const x=$json;
const op=x.operation;
const allowed=['get_product','get_products','get_variation','search_products','availability_check'];
const valid = allowed.includes(op) &&
  x.request_id && x.caller_context &&
  ['product_read','checkout_validation','cart_validation','sales'].includes(x.caller_context.purpose);
if(!valid) throw new Error('WF-11 invalid request contract');
return [{json:{
  request_id:String(x.request_id),
  operation:op,
  caller_context:x.caller_context,
  product_id:x.product_id ?? null,
  sku:x.sku ?? null,
  variation_id:x.variation_id ?? null,
  search:x.search ?? null,
  page:x.page ?? 1,
  per_page:Math.min(Number(x.per_page ?? 20),50)
}}];

const x=$json;
let gatewayOperation='get_product';
if(x.operation==='get_products'||x.operation==='search_products') gatewayOperation='get_products';
if(x.operation==='get_variation') gatewayOperation='get_variation';
if(x.operation==='availability_check') gatewayOperation='get_product';
return [{json:{...x,gateway_operation:gatewayOperation}}];
